def localFrameRowPerm (r : Fin 4) : Equiv.Perm (Fin 4) :=
  if r = 0 then Equiv.refl _
  else if r = 1 then Equiv.swap 2 3
  else if r = 2 then Equiv.swap 0 1
  else (Equiv.swap 0 1).trans (Equiv.swap 2 3)

