def localFrameRowSign (r s : Fin 4) : ℝ :=
  if r = 0 then 1
  else if r = 1 then (if s = 1 then -1 else 1)
  else if r = 2 then (if s = 3 then -1 else 1)
  else (if s = 0 ∨ s = 3 then -1 else 1)

